(()=>{'use strict';const entries=[];let box;let prior=[];try{prior=JSON.parse(sessionStorage.getItem('starfall-error-log')||'[]');}catch{}const clean=v=>String(v||'Unknown error').replace(/SF-[A-Za-z0-9_-]+/g,'[passkey removed]').replace(/https?:\/\/[^\s)]+/g,url=>{try{const u=new URL(url);return u.origin+u.pathname;}catch{return '[URL]';}}).slice(0,900);function record(message){entries.push(new Date().toISOString()+' · '+clean(message));if(entries.length>12)entries.shift();try{sessionStorage.setItem('starfall-error-log',JSON.stringify(entries));}catch{}if(!box){box=document.createElement('details');box.className='starfall-error-log';box.innerHTML='<summary aria-label="Open error log">×</summary><div><b>Error log</b><pre></pre><a href="/profile.html#tickets">OPEN SUPPORT TICKET →</a></div>';document.body.append(box);const style=document.createElement('style');style.textContent='.starfall-error-log{position:fixed;right:16px;bottom:16px;z-index:10000;color:#eef8ff;font:12px system-ui;background:#101c28;border:1px solid var(--skin-accent,#89cfea);border-radius:8px;box-shadow:0 0 20px #0008}.starfall-error-log summary{cursor:pointer;padding:8px 14px;font-size:22px;list-style:none}.starfall-error-log>div{padding:14px;max-width:min(440px,85vw)}.starfall-error-log pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto}.starfall-error-log a{color:#a7e1ff}';document.head.append(style);}box.querySelector('pre').textContent=entries.join('\n');}window.starfallErrorLog={text:()=>entries.join('\n'),record};prior.slice(-12).forEach(record);window.addEventListener('error',e=>record(e.message||(e.target?.tagName?('Failed to load '+e.target.tagName):'Resource error')),true);window.addEventListener('unhandledrejection',e=>record(e.reason?.message||e.reason));})();
